package com.aaliyun.leadnews.behavior.service;
import com.aaliyun.leadnews.behavior.mapper.BehaviorMapper;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class ViewBatchPersistenceService {private final BehaviorMapper db;public ViewBatchPersistenceService(BehaviorMapper db){this.db=db;}@Scheduled(fixedDelayString="${leadnews.behavior.view-flush-millis:1000}")@Transactional public void flush(){List<Map<String,Object>> rows=db.pendingViews();if(rows.isEmpty())return;Map<Long,Long> totals=new HashMap<>();List<Long> ids=new ArrayList<>(rows.size());for(Map<String,Object>r:rows){long id=((Number)r.get("id")).longValue(),article=((Number)r.get("articleId")).longValue(),delta=((Number)r.get("delta")).longValue();ids.add(id);totals.merge(article,delta,Long::sum);}totals.forEach((article,delta)->db.addStat(article,0,delta));db.markApplied(ids);}}
